function validate([segments]) {
  if (!Array.isArray(segments) || segments.length < 1 || segments.length > 20000) return 'segments needs 1 to 20000 entries.';
  const seen = new Set();
  for (const s of segments) {
    if (!Array.isArray(s) || s.length !== 3 || !s.every(Number.isInteger)) return 'Each segment is [start, end, color] with integers.';
    const [start, end, color] = s;
    if (start < 1 || end > 100000 || start >= end) return 'Each segment needs 1 <= start < end <= 10^5.';
    if (color < 1 || color > 1e9) return 'Each color is between 1 and 10^9.';
    if (seen.has(color)) return 'All colors must be distinct.';
    seen.add(color);
  }
  return null;
}

