function splitPainting(segments) {
  const delta = new Map();
  for (const [start, end, color] of segments) {
    delta.set(start, (delta.get(start) ?? 0) + color);
    delta.set(end, (delta.get(end) ?? 0) - color);
  }

  const points = [...delta.keys()].sort((a, b) => a - b);
  const painting = [];
  let mix = 0;

  for (let i = 0; i < points.length - 1; i++) {
    mix += delta.get(points[i]);
    if (mix > 0) {
      painting.push([points[i], points[i + 1], mix]);
    }
  }
  return painting;
}

