function splitPainting(segments) {
  // Find the exact color set of every unit cell [x, x + 1), then merge neighbouring cells with identical sets.
  let maxEnd = 0;
  for (const s of segments) maxEnd = Math.max(maxEnd, s[1]);
  const result = [];
  let open = null;
  for (let x = 1; x <= maxEnd; x++) {
    const colors = x < maxEnd ? segments.filter(s => s[0] <= x && x < s[1]).map(s => s[2]).sort((a, b) => a - b) : [];
    const key = colors.join(',');
    if (open && open.key === key) { open.right = x + 1; continue; }
    if (open && open.key !== '') result.push([open.left, open.right, open.sum]);
    open = { key, left: x, right: x + 1, sum: colors.reduce((a, b) => a + b, 0) };
  }
  if (open && open.key !== '') result.push([open.left, open.right, open.sum]);
  return result;
}

