function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = size === 'small';
  const n = small ? pick(1, 6) : 2000;
  const maxCoord = small ? pick(3, 15) : [300, 5000, 100000][pick(0, 2)];
  const maxColor = small ? 30 : 1000000000;
  const colors = new Set();
  while (colors.size < n) colors.add(pick(1, maxColor));
  const palette = [...colors];
  const segments = [];
  for (let i = 0; i < n; i++) {
    const a = pick(1, maxCoord - 1);
    const b = pick(a + 1, Math.min(maxCoord, a + (small || rand() < 0.5 ? maxCoord : 50)));
    segments.push([a, b, palette[i]]);
  }
  return [segments];
}
